record.field:
module = self.env['ir.module.module']._get('sports_club_playtomic')
for record in self:
    record['x_module_sports_club_playtomic'] = module.state == 'installed'

if not (env.context.get('install_module') == 'sports_club_playtomic' and env.context.get('install_mode')):
    installed = module.state == 'installed'
    if record.x_module_sports_club_playtomic and not installed:
        # First, import the Product Conversion industry module because it is not available in ir_module_module.
        import_action = env['ir.module.module'].with_context(module_name='sports_club_playtomic').button_immediate_install_app()
        env['base.import.module'].browse(import_action['res_id']).import_module()
    elif not record.x_module_sports_club_playtomic and installed:
        module = env['ir.module.module']._get('sports_club_playtomic')
        if module: module.button_immediate_uninstall()
